\section*{Assumptions}
\begin{enumerate}[label={A\arabic*}.]
\item \textbf{Smoothness.} $f$ is $L$‑smooth:
\[
\forall x,y\in\R^d,\qquad
f(y)\le f(x)+\ip{\grad f(x)}{y-x}+\frac{L}{2}\norm{y-x}^2 .
\tag{A1}
\]
\item \textbf{Lower boundedness.} $f^{\star}:=\inf_{w}f(w)>-\infty$.
\tag{A2}
\item \textbf{Stochastic gradient.} For every $t$,
\[
\E_{\xi_t}[g_t\mid w_t]=\grad f(w_t),\qquad
\E_{\xi_t}\!\big[\norm{g_t-\grad f(w_t)}^2\mid w_t\big]\le\sigma^2 .
\tag{A3}
\]
\item \textbf{Unbiased quantizer with bounded variance.} There exists $\omega\ge0$ such that for any $u\in\R^d$,
\[
\E_{\Q}\!\big[\Q(u)\mid u\big]=u,\qquad
\E_{\Q}\!\big[\norm{\Q(u)}^2\mid u\big]\le (1+\omega)\norm{u}^2 .
\tag{A4}
\]
\item \textbf{Stepsize.} The learning rate is constant $\eta_t\equiv\eta$ satisfying
\[
0<\eta\le\frac{1}{L(1+\omega)} .
\tag{A5}
\]
\end{enumerate}

\section*{Main Convergence Theorem}
\begin{theorem}[Non‑convex convergence of QSGD]\label{thm:main}
Under Assumptions A1–A5, for any $T\ge1$ the iterates generated by \eqref{1} satisfy
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\big[\norm{\grad f(w_t)}^2\big]
\;\le\;
\underbrace{\frac{2\big(f(w_0)-f^{\star}\big)}{\eta T}}_{\text{optimization term}}
\;+\;
\underbrace{L\eta\big(\sigma^2+\omega G^2\big)}_{\text{variance term}},
\tag{2}
\]
where $G^2:=\sup_{t}\E\!\big[\norm{g_t}^2\big]$ (finite under A3 and A4). Consequently,
\[
\min_{0\le t<T}\E\!\big[\norm{\grad f(w_t)}^2\big]\;=\;O\!\Big(\frac{1}{\sqrt{T}}\Big)
\quad\text{when }\eta\asymp T^{-1/2}.
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}
\item \textbf{Stability.} The bound \eqref{2} holds for any $\eta$ respecting (A5); larger $\omega$ (more aggressive quantization) merely inflates the variance term.
\item \textbf{Hyper‑parameter sensitivity.} The optimal constant stepsize is $\eta^{\star}= \sqrt{\frac{2\big(f(w_0)-f^{\star}\big)}{L\big(\sigma^2+\omega G^2\big)T}}$, yielding the $O(T^{-1/2})$ rate.
\item \textbf{Comparison.} Setting $\omega=0$ recovers the standard non‑convex SGD bound; thus quantization incurs an additive penalty proportional to $\omega$.
\item \textbf{Special case – deterministic gradients.} If $\sigma=0$, the bound reduces to $O\big(\frac{1}{\eta T}+L\eta\omega G^2\big)$, showing that with exact gradients quantization still slows convergence unless $\eta\to0$.
\end{itemize}

\section*{Discussion}
The theorem demonstrates that unbiased quantization does not destroy the classical $O(1/\sqrt{T})$ convergence guarantee for smooth non‑convex optimization; the price paid is a multiplicative factor $1+\omega$ in the variance term. This matches intuition: quantization behaves like an additional source of noise. The result is tight up to constants and aligns with existing analyses of QSGD \cite{Alistarh2017}.

